// ExportCount says "{words, plural, one {# word} other {# words}} · {lines, plural, one {# saved line} other {# saved lines}} · from all devices"
// in the language the app shows under cx.
//
// Export page: what the export writes, counted.
func ExportCount(cx *core.Scope, words int, lines int) string {
	return For(cx).ExportCount(words, lines)
}

// ExportCount is the package's ExportCount in the language of msgs.
func (msgs Messages) ExportCount(words int, lines int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.ExportCount(words, lines))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ExportCount; f != nil {
			return f(words, lines)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(words)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(words))))
				b.WriteString(" word")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(words))))
				b.WriteString(" words")
			}
			b.WriteString(" · ")
			switch i18n.Cardinal("en", float64(lines)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(lines))))
				b.WriteString(" saved line")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(lines))))
				b.WriteString(" saved lines")
			}
			b.WriteString(" · from all devices")
			return b.String()
		case "ja":
			return "単語 " + i18n.FormatNumber("ja", float64(words)) + " 件 · 保存したセリフ " + i18n.FormatNumber("ja", float64(lines)) + " 件 · すべての端末から"
		case "ko":
			return "단어 " + i18n.FormatNumber("ko", float64(words)) + "개 · 저장한 대사 " + i18n.FormatNumber("ko", float64(lines)) + "개 · 모든 기기에서"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(words)) + " 个生词 · " + i18n.FormatNumber("zh-Hans", float64(lines)) + " 句收藏 · 来自所有设备"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(words)) + " 個生詞 · " + i18n.FormatNumber("zh-Hant", float64(lines)) + " 句收藏 · 來自所有裝置"
		}
	}
}

