// LearnDueIn is the package's LearnDueIn in the language of msgs.
func (msgs Messages) LearnDueIn(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.LearnDueIn(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].LearnDueIn; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString("Next in ")
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" day")
			default:
				b.WriteString("Next in ")
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" days")
			}
			return b.String()
		case "ja":
			return "次回：" + i18n.FormatNumber("ja", float64(count)) + " 日後"
		case "ko":
			return "다음: " + i18n.FormatNumber("ko", float64(count)) + "일 후"
		case "zh-Hans":
			return "下次：" + i18n.FormatNumber("zh-Hans", float64(count)) + " 天后"
		case "zh-Hant":
			return "下次：" + i18n.FormatNumber("zh-Hant", float64(count)) + " 天後"
		}
	}
}

